const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Mount Vesuvius coordinates (approximate peak)
  const vesuvius = ee.Geometry.Point(14.4337, 40.8213);
  // Define the "cone" as a buffer around the peak, e.g., 2km radius
  const cone = vesuvius.buffer(2000); // 2 km radius

  const startDate = '2022-01-02';
  const endDate = '2022-01-03'; // To include images from the start date

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterDate(startDate, endDate)
    .filterBounds(cone);

  const colSize = await collection.size().getInfo();

  if (colSize === 0) {
    console.log("No Landsat 8 images found for Mount Vesuvius on January 2, 2022.");
    console.log("C1");
    return;
  }

  // Get the first image (should be only one for a specific day)
  const image = collection.first();
  const imageId = await image.id().getInfo();
  console.log(`Landsat 8 image found: ${imageId}`);

  // Landsat 8 QA_PIXEL band flags for clouds
  // Bits 3 and 5 are for clouds (cloud, cloud shadow). Bit 9 for cirrus.
  // We'll consider opaque clouds (bit 3) and high confidence clouds (bit 5).
  // Bit 3: Cloud (0 = No, 1 = Yes)
  // Bit 5: Cloud Confidence (00 = Not Set, 01 = Low, 10 = Medium, 11 = High)
  // We're interested in medium or high confidence clouds (10 or 11 for bit 5),
  // and also the basic cloud flag (bit 3).

  // Function to extract cloud information from QA_PIXEL band
  const getCloudMask = function(image) {
    const qa = image.select('QA_PIXEL');

    // Bits 3 (cloud) and 5 (cloud confidence)
    // See Landsat 8 Collection 2 Surface Reflectance QA_PIXEL band documentation
    // Bit 3: cloud (1 = cloud)
    // Bit 5-6: cloud confidence (00=none, 01=low, 10=medium, 11=high)
    const cloudBitmask = 1 << 3; // Bit 3
    const cloudConfidenceBitmask = 3 << 5; // Bits 5-6

    // Pixels are considered cloudy if the cloud bit is set OR
    // if cloud confidence is medium or high.
    const isCloud = qa.bitwiseAnd(cloudBitmask).neq(0)
                   .or(qa.bitwiseAnd(cloudConfidenceBitmask).eq(1 << 5)) // Medium confidence
                   .or(qa.bitwiseAnd(cloudConfidenceBitmask).eq(2 << 5)); // High confidence

    // Return an image with 1 for cloud, 0 for clear.
    return isCloud.rename('cloud').selfMask(); // selfMask will set non-cloud pixels to 0
  };

  const cloudMask = getCloudMask(image);

  // 3. Processing: Calculate total pixels and cloudy pixels within the cone
  // Scale for reduceRegion (Landsat 8 resolution is 30m, but 100m for calculation is fine)
  const scale = 100;
  const maxPixels = 1e9;

  // Count total pixels in the cone
  const totalPixels = image.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: cone,
    scale: scale,
    maxPixels: maxPixels
  });

  const totalPixelCount = await totalPixels.values().get(0).getInfo();

  if (totalPixelCount === 0 || totalPixelCount === null) {
    console.log("No valid pixels within the defined cone area for Mount Vesuvius.");
    console.log("C2");
    return;
  }

  // Count cloudy pixels in the cone using the cloud mask
  const cloudyPixels = cloudMask.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: cone,
    scale: scale,
    maxPixels: maxPixels
  });

  const cloudyPixelCount = await cloudyPixels.get('cloud').getInfo();

  if (cloudyPixelCount === null) {
    console.log("Calculation of cloudy pixels failed.");
    console.log("C3");
    return;
  }

  // 4. Calculation: Percentage of cloud cover
  const cloudPercentage = (cloudyPixelCount / totalPixelCount) * 100;

  // 5. Validation & Final Answer
  console.log(`Total pixels in cone: ${totalPixelCount}`);
  console.log(`Cloudy pixels in cone: ${cloudyPixelCount}`);
  console.log(`Cloud cover percentage: ${cloudPercentage.toFixed(2)}%`);

  // Define "fully covered" as >= 95% cloud cover
  if (cloudPercentage >= 95) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
